import io, sys
sys.path.insert(0, '.')
import wlogseg
from wlogseg import pack, unpack, verify, iter_segments, read_all, compute_crc, WSegError

for name in ('assets/sample.wlsg', 'assets/sample_empty.wlsg'):
    data = open(name, 'rb').read()
    segs = unpack(data)
    print(name, 'verify=', verify(data), 'roundtrip=', pack(segs) == data)
    print('  segs=', [(i, len(p)) for i, p in segs])
    print('  stream=', read_all(io.BytesIO(data)) == segs)

print('crc vector 123456789 ->', hex(compute_crc(b'123456789')))

d = open('assets/sample.wlsg', 'rb').read()
# truncated
for n in (4, 10, 20, 100, len(d) - 1):
    try:
        unpack(d[:n])
        print('trunc', n, 'NO ERROR')
    except WSegError as e:
        print('trunc', n, e.kind)

# bad magic
b = bytearray(d); b[0:4] = b'XXXX'
try: unpack(bytes(b))
except WSegError as e: print('magic ->', e.kind)
# bad version
b = bytearray(d); b[4] = 9
try: unpack(bytes(b))
except WSegError as e: print('version ->', e.kind)
# tampered payload
b = bytearray(d); b[30] ^= 0xFF
try: unpack(bytes(b))
except WSegError as e: print('tamper ->', e.kind, '| verify=', verify(bytes(b)))
# tampered index
b = bytearray(d); b[350] ^= 0xFF
try: unpack(bytes(b))
except WSegError as e: print('tamper index ->', e.kind)
# bad seg count
b = bytearray(d); b[6] = 7
try: unpack(bytes(b))
except WSegError as e: print('count 7 ->', e.kind)
b = bytearray(d); b[6] = 3
try: unpack(bytes(b))
except WSegError as e: print('count 3 ->', e.kind)
# bad seg length -> structure
b = bytearray(d); b[20] = 0xFF
try: unpack(bytes(b))
except WSegError as e: print('seglen ->', e.kind)

# pack validation
for bad in ([(-1, b'x')], [(70000, b'x')], [(1, 'str')], [(1, None)], [('a', b'x')], [(True, b'x')]):
    try:
        pack(bad); print('BAD ACCEPTED', bad)
    except WSegError as e:
        print('reject', bad, '->', e.kind)

# round trips
cases = [[], [(0, b'')], [(65535, b'x' * 7)], [(1, b'a'), (2, b''), (3, b'b' * 100)]]
for c in cases:
    blob = pack(c)
    assert unpack(blob) == c, c
    assert read_all(io.BytesIO(blob)) == c
    assert verify(blob)
print('roundtrips ok; lengths=', [len(pack(c)) for c in cases])

# stream must not use read() whole
class Strict(io.BytesIO):
    def read(self, n=-1):
        assert isinstance(n, int) and n > 0, f'bad read({n})'
        return super().read(n)
print('strict stream=', read_all(Strict(d)) == unpack(d))

# laziness
class Counting(Strict):
    total = 0
    def read(self, n):
        Counting.total += n
        return super().read(n)
g = iter_segments(Counting(d))
next(g)
print('lazy bytes read after 1 seg:', Counting.total, 'of', len(d))

# stream checksum failure
b = bytearray(d); b[-1] ^= 0xFF
try:
    read_all(io.BytesIO(bytes(b)))
except WSegError as e:
    print('stream bad crc ->', e.kind)
try:
    read_all(io.BytesIO(d[:-3]))
except WSegError as e:
    print('stream truncated ->', e.kind)
print('verify no raise:', verify(b'x'), verify(None), verify(b''), verify(b'WLSG' + b'\x00' * 40))
